import{_ as o,a8 as e,o as n,c as l,ah as i,K as a}from"./chunks/framework.CIrX4_tc.js";import"./chunks/theme.DhGbIGPm.js";const g=JSON.parse('{"title":"命名实体识别（NER）","description":"","frontmatter":{"title":"命名实体识别（NER）","abstract":"命名实体识别技术讲解，涵盖从文本中识别人名地名等实体的任务定义、标注方案、经典方法演进与核心挑战。","created":"2026-07-10T00:00:00.000Z","tags":["NLP","序列标注"],"type":"概念解释","category":["🤖 AI大模型","NLP基础"]},"headers":[],"relativePath":"vault/Knowledge/AI/命名实体识别（NER）.md","filePath":"vault/Knowledge/AI/命名实体识别（NER）.md","lastUpdated":1790655645000}'),s={name:"vault/Knowledge/AI/命名实体识别（NER）.md"};function h(_,t,c,b,R,E){const d=e("NolebaseGitContributors"),r=e("NolebaseGitChangelog");return n(),l("div",null,[t[0]||(t[0]=i('<h1 id="命名实体识别-ner" tabindex="-1">命名实体识别（NER） <a class="header-anchor" href="#命名实体识别-ner" aria-label="Permalink to “命名实体识别（NER）”">​</a></h1><p>NER 旨在从文本中识别出预定义类别的实体（人名、地名、机构名、时间等），属于<strong>序列标注</strong>任务。</p><h2 id="标注方案" tabindex="-1">标注方案 <a class="header-anchor" href="#标注方案" aria-label="Permalink to “标注方案”">​</a></h2><table tabindex="0"><thead><tr><th>方案</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td>BIO</td><td>B-begin / I-inside / O-outside</td><td>B-PER, I-PER, O</td></tr><tr><td>BIOES</td><td>+ E-end / S-single</td><td>B-PER, I-PER, E-PER, S-LOC</td></tr><tr><td>IO</td><td>仅分内/外</td><td>无法区分边界</td></tr></tbody></table><h2 id="经典方法演进" tabindex="-1">经典方法演进 <a class="header-anchor" href="#经典方法演进" aria-label="Permalink to “经典方法演进”">​</a></h2><table tabindex="0"><thead><tr><th>时代</th><th>方法</th><th>特点</th></tr></thead><tbody><tr><td>规则</td><td>字典+正则</td><td>准确率高，召回率低</td></tr><tr><td>统计</td><td>CRF（条件随机场）</td><td>手工特征 + Viterbi 解码</td></tr><tr><td>DL</td><td>BiLSTM-CRF</td><td>自动特征提取 + CRF 约束</td></tr><tr><td>预训练</td><td>BERT-CRF</td><td>上下文表示 + CRF 层</td></tr><tr><td>LLM</td><td>GPT/BERT 实体分类</td><td>用 prompt 或微调做 NER</td></tr></tbody></table><h2 id="核心挑战" tabindex="-1">核心挑战 <a class="header-anchor" href="#核心挑战" aria-label="Permalink to “核心挑战”">​</a></h2><ul><li><strong>嵌套实体</strong>（如 &quot;北京大学&quot; 中的 &quot;北京&quot; 是地点、&quot;北京大学&quot; 是机构）</li><li><strong>未见实体</strong>：开放域 OOV 实体</li><li><strong>实体消歧</strong>：如 &quot;苹果&quot; 是水果还是公司</li></ul>',8)),a(d),a(r)])}const N=o(s,[["render",h]]);export{g as __pageData,N as default};
